function renderBusinesses(){let list=cityBiz().filter(b=>(bizCat==='Todos'||b.cat===bizCat)&&matches(bizQuery,b.name+' '+b.cat+' '+b.svc.join(' ')+' '+b.hoods.join(' '))).sort((a,b)=>b.recN-a.recN);const sponsors=list.filter(b=>b.spon),organic=list.filter(b=>!b.spon);return `<div class="page-head"><div><h1>Negócios locais</h1><p>Indicados pela comunidade de ${esc(state.city)}.</p></div>${!readonly()?btn('Minha página','my-biz','','tonal','storefront'):''}</div>${readonlyHtml()}${!readonly()?`<button type="button" class="context-strip" data-action="create-request" style="width:100%;text-align:left">${icon('build')}<span class="grow"><b>Precisa contratar?</b><br><span class="small">Descreva o serviço e receba até ${REQUEST_LIMIT} propostas.</span></span>${icon('chevron_right')}</button>`:''}<md-filled-text-field id="biz-search" class="search-input" type="search" label="Serviço, nome ou bairro" value="${esc(bizQuery)}">${icon('search','leading-icon')}</md-filled-text-field>${filterChips(['Todos',...new Set(cityBiz().map(b=>b.cat))].map(x=>[x,x]),bizCat,'biz-filter')}<div id="business-results">${sponsors.length?`<section class="section">${sectionTitle('Patrocinado')}<div class="card-grid">${sponsors.map(businessCard).join('')}</div></section>`:''}<section class="section">${sectionTitle('Indicações da comunidade')}<div class="card-grid">${organic.map(businessCard).join('')}</div>${!organic.length?empty('Nenhum negócio encontrado','Experimente outro serviço ou bairro.','storefront'):''}</section></div><p class="small muted" style="margin-top:20px">Destaques pagos ficam separados das indicações da comunidade.</p>${!readonly()?`<section class="section">${btn('Indicar um negócio','indicate','','outlined','thumb_up')}</section>`:''}`;}
